def max_value_on_paths(N, grid_values):
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        grid[x - 1][y - 1] = value

    # Initialize the dp table with the values from the grid
    dp = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            dp[i][j] = grid[i][j]

    # Fill in the dp table
    for i in range(N - 1, -1, -1):
        for j in range(N - 1, -1, -1):
            if i == N - 1 and j == N - 1:
                continue
            dp[i][j] = max(dp[i][j], dp[i + 1][j], dp[i][j + 1]) + grid[i][j]

    return dp[0][0]
```
