def max_product(num_str, N, K):
    # Base case: If K is 0, return the product of the numbers in num_str
    if K == 0:
        result = 1
        for num in num_str:
            result *= int(num)
        return result

    # Initialize variables
    max_product = 0
    for i in range(N - 1):
        # Get the product of the numbers to the left and right of the ith digit
        left_product = 1
        for j in range(i):
            left_product *= int(num_str[j])
        right_product = 1
        for j in range(i + 1, N):
            right_product *= int(num_str[j])

        # Calculate the maximum product by inserting a multiplication sign between the ith and (i + 1)th digits
        max_product = max(max_product, left_product * right_product)

    # Recursive call: Insert a multiplication sign between the ith and (i + 1)th digits and solve the subproblem
    return max(max_product, max_product(num_str[:i] + num_str[i:i + 1] + num_str[i + 1:], N, K - 1))
