def calculate_arrangements(n, m, a):
    # Initialize a 2D array dp to keep track of the number of arrangements
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the first column of dp with the number of arrangements for 0 pots
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill in the rest of dp using the recurrence relation
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j - 1] * a[i - 1] + dp[i - 1][j] * (a[i - 1] - 1)

    # Return the result modulo (10^6 + 7)
    return dp[n][m] % (10**6 + 7)
```

